animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
will-change: transform, opacity;
&[data-state="delayed-open"] {
  &[data-side="top"] {
    animation-name: ${down};
  }
  &[data-side="right"] {
    animation-name: ${left};
  }
  &[data-side="bottom"] {
    animation-name: ${up};
  }
  &[data-side="left"] {
    animation-name: ${right};
  }
}

height: 20px;
width: 20px;
flex-shrink: 0;
display: flex;
align-items: center;
justify-content: center;
padding: var(--openui-space-3xs, 2px);
